const texto = $input.first().json.output;
const itens = texto.split(/\\/);
return itens.filter(item => item.trim() !== '').map(item => ({ item: item.trim() }));

const coleta = $('Coleta').item.json;
const nome = coleta.nome || 'Não identificado';
const tel = coleta.telefone || '';
const tipo = coleta.tipo || 'midia';
const msg = coleta.mensagem || '';

const tipoLabel = { imageMessage: '📷 Imagem', videoMessage: '🎬 Vídeo', audioMessage: '🎵 Áudio' }[tipo] || '📎 Mídia';
const temLegenda = msg && !msg.startsWith('📷') && !msg.startsWith('🎬') && !msg.startsWith('🎵');
const legenda = temLegenda ? '\nLegenda: _' + msg + '_' : '';
const telLimpo = tel.replace('@s.whatsapp.net','').replace(/^55/,'').replace(/\D/g,'');

const alertText = '🔔 *Mídia Recebida — Damares Estética*\n\n' +
  '*Cliente:* ' + nome + '\n' +
  '*Telefone:* ' + telLimpo + legenda + '\n' +
  '*Mídia:* ' + tipoLabel + '\n\n' +
  '_Mensagem de mídia recebida — verifique no WhatsApp se necessário._';

return [{ json: { alertText } }];

const inp = $input.first().json;

function normDate(v) {
  if (!v) return '';
  v = v.trim();
  // YYYY-MM-DD — passar direto
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  const parts = v.split('/');
  if (parts.length === 2) {
    // DD/MM sem ano — infere o próximo ano válido
    const now = new Date();
    const day   = ('0' + parts[0].trim()).slice(-2);
    const month = ('0' + parts[1].trim()).slice(-2);
    let year = now.getFullYear();
    const candidate = new Date(year + '-' + month + '-' + day + 'T12:00:00');
    if (candidate < now) year++;
    return year + '-' + month + '-' + day;
  }
  if (parts.length === 3) {
    const day   = ('0' + parts[0].trim()).slice(-2);
    const month = ('0' + parts[1].trim()).slice(-2);
    const year  = parts[2].trim();
    return year + '-' + month + '-' + day;
  }
  // Formato não reconhecido (só número, nome de dia etc.) → vazio
  // O agente deve ter pedido esclarecimento antes de chamar a ferramenta
  return '';
}

const date   = normDate(inp.date || inp.data || '');
const period = (inp.period || inp.periodo || 'qualquer').toLowerCase();

return [{ json: { date, period } }];

const inp = $('Normaliza Input Disponibilidade').first().json;
const date   = inp.date;
const period = inp.period;

// ── Feriados nacionais brasileiros (dias úteis apenas) ─────────────────
const feriados = new Set([
  '2026-01-01','2026-02-16','2026-02-17','2026-04-03','2026-04-21',
  '2026-05-01','2026-06-04','2026-09-07','2026-10-12','2026-11-02',
  '2026-11-20','2026-12-25',
  '2027-01-01','2027-02-08','2027-02-09','2027-03-26','2027-04-21',
  '2027-05-27','2027-09-07','2027-10-12','2027-11-02','2027-11-15',
]);

// ── Eventos do dia — converte para hora local BRT (UTC-3) ──────────────
function toLocalH(dateTimeStr) {
  const d = new Date(dateTimeStr);
  return (d.getUTCHours() - 3 + 24) % 24 + d.getUTCMinutes() / 60;
}
const events = $input.all().map(item => {
  const ev = item.json;
  if (!ev.start || !ev.start.dateTime) return null;
  return { startH: toLocalH(ev.start.dateTime), endH: toLocalH(ev.end?.dateTime || ev.start.dateTime) };
}).filter(Boolean);

// ── Formata data em extenso (sem barras) ──────────────────────────────
function fmtDate(d) {
  try {
    return new Date(d + 'T12:00:00').toLocaleDateString('pt-BR', {
      weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
    });
  } catch(e) { return d; }
}
const dd  = fmtDate(date);
const dow = new Date(date + 'T12:00:00').getDay();

if (dow === 0 || dow === 6) {
  const diaNome = dow === 0 ? 'domingos' : 'sábados';
  return [{ json: { disponivel: false, slots: [], date, dateDisplay: dd,
    mensagem: `Não realizo atendimentos aos ${diaNome} 🌿 Meu horário é de segunda a sexta. Gostaria de escolher outro dia?` } }];
}
if (feriados.has(date)) {
  return [{ json: { disponivel: false, slots: [], date, dateDisplay: dd,
    mensagem: 'Esse dia é feriado e não realizo atendimentos 🌿 Gostaria de escolher outra data?' } }];
}

const duracoes = { manha: [8, 13], tarde: [13, 20], qualquer: [8, 20] };
const [rangeStart, rangeEnd] = duracoes[period] || [8, 20];

const slots = [];
let h = rangeStart;
while (h + 1 <= rangeEnd) {
  const ocupado = events.some(ev => ev.startH < (h + 1.5) && ev.endH > h);
  if (!ocupado) slots.push(String(h).padStart(2, '0') + ':00');
  h += 1.5;
  h = Math.ceil(h);
}

const per = period === 'manha' ? 'manhã' : period === 'tarde' ? 'tarde' : 'dia';

if (!slots.length) {
  return [{ json: { disponivel: false, slots: [], date, dateDisplay: dd,
    mensagem: 'Infelizmente não tenho horários disponíveis em ' + dd + ' no período da ' + per + ' 🌿 Gostaria de tentar outra data ou período?',
    eventosEncontrados: events } }];
}
return [{ json: { disponivel: true, slots, date, dateDisplay: dd, period,
  mensagem: 'Tenho os seguintes horários disponíveis em ' + dd + ' (' + per + '): *' + slots.join(', ') + '*. Qual desses horários funciona melhor para você? 🌿',
  eventosEncontrados: events } }];

const inp = $input.first().json;

function normDate(v) {
